class DiceGame extends GameEngine{constructor(e,t,n){super(e,"dice",t),this.prizes=n,this.results=[0,0,0],this.isRolling=!1}render(e){document.getElementById(e).innerHTML='\n      <div class="game-container">\n        <div class="game-header">\n          <h2>🎲 Xúc Sắc</h2>\n          <p>Tung 3 xúc sắc để nhận giải thưởng</p>\n          <div class="timer" id="timer">0s</div>\n        </div>\n\n        <div class="dice-container">\n          <div class="dice-roller">\n            <div class="dice" id="dice1">1</div>\n            <div class="dice" id="dice2">1</div>\n            <div class="dice" id="dice3">1</div>\n          </div>\n\n          <button class="roll-button" id="rollBtn" onclick="rollDice()">\n            🎲 TUNG NGAY\n          </button>\n\n          <div class="roll-result" id="rollResult"></div>\n\n          <div class="roll-stats">\n            <p id="rollSum"></p>\n            <p id="rollMessage"></p>\n          </div>\n        </div>\n      </div>\n    ',this.startTimer()}async roll(){const e=document.getElementById("rollBtn");if(this.isRolling||e.disabled)return;this.isRolling=!0,e.disabled=!0,e.textContent="⏳ ĐANG TUNG...";const t=[document.getElementById("dice1"),document.getElementById("dice2"),document.getElementById("dice3")];t.forEach(e=>e.classList.add("rolling"));let n=setInterval(()=>{t.forEach(e=>{e.textContent=Math.floor(6*Math.random())+1})},50);await new Promise(e=>setTimeout(e,1500)),clearInterval(n),this.results=[Math.floor(6*Math.random())+1,Math.floor(6*Math.random())+1,Math.floor(6*Math.random())+1],t.forEach((e,t)=>{e.textContent=this.results[t],e.classList.remove("rolling")});const i=this.results.reduce((e,t)=>e+t,0),s=i>=15,o=s?"🎉 Bạn Thắng Rồi!":"✨ Hãy Thử Lại Lần Sau";document.getElementById("rollSum").innerHTML=`<strong>Tổng: ${i}</strong>`,document.getElementById("rollMessage").textContent=o,this.playSound(s?"win":"lose"),await new Promise(e=>setTimeout(e,1e3)),this.endGame(0)}playSound(e){try{const t=new(window.AudioContext||window.webkitAudioContext),n=t.createOscillator(),i=t.createGain();if(n.connect(i),i.connect(t.destination),"win"===e){n.frequency.setValueAtTime(600,t.currentTime),n.frequency.exponentialRampToValueAtTime(1e3,t.currentTime+.3),i.gain.setValueAtTime(.3,t.currentTime),i.gain.exponentialRampToValueAtTime(.01,t.currentTime+.3),n.start(t.currentTime),n.stop(t.currentTime+.3);const e=t.createOscillator(),s=t.createGain();e.connect(s),s.connect(t.destination),e.frequency.value=800,s.gain.setValueAtTime(.2,t.currentTime+.2),s.gain.exponentialRampToValueAtTime(.01,t.currentTime+.5),e.start(t.currentTime+.2),e.stop(t.currentTime+.5)}else n.frequency.value=300,i.gain.setValueAtTime(.2,t.currentTime),i.gain.exponentialRampToValueAtTime(.01,t.currentTime+.5),n.start(t.currentTime),n.stop(t.currentTime+.5)}catch(e){console.warn("Audio not available:",e)}}endGame(e){this.state="completed";const t=this.prizes[e||0];this.selectedPrize=t;const n=this.getCompletionTime(),i=this.results.reduce((e,t)=>e+t,0);console.log(`✅ Dice game completed in ${n}s (Total: ${i})`),fetch("/api/game/result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({session_code:this.sessionCode,game_type:this.gameType,prize_id:t.id,completion_time:n,extra_data:{dice_total:i,dice_values:this.results}})}).catch(e=>console.error(e)),this.showResultScreen(t)}showResultScreen(e){const t=e.color||"#8b5cf6",n=this.results.reduce((e,t)=>e+t,0),i=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${t}">🎉</div>\n        <h2 class="result-title">Kết Quả</h2>\n        <p class="result-message">Bạn đã tung được</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 1.5rem; margin-bottom: 10px; letter-spacing: 10px;">\n            ${this.results[0]} 🎲 ${this.results[1]} 🎲 ${this.results[2]}\n          </div>\n          <strong style="color: ${t}; font-size: 1.5rem;">Tổng: ${n}</strong>\n          <div style="font-size: 2.5rem; margin: 20px 0;">${e.icon||"🎁"}</div>\n          <strong style="color: ${t}; font-size: 1.4rem;">${e.name}</strong>\n          ${e.cash_amount?`<p>💰 ${e.cash_amount.toLocaleString()}đ</p>`:""}\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            ✅ Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="shareResult()">\n            📤 Chia Sẻ\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=i}startTimer(){this.startTime=Date.now();const e=setInterval(()=>{const t=Math.floor((Date.now()-this.startTime)/1e3),n=document.getElementById("timer");n?n.textContent=t+"s":clearInterval(e)},1e3)}}function rollDice(){window.diceGameInstance&&window.diceGameInstance.roll()}console.log("✅ DiceGame class loaded");